import java.util.Arrays;

public class Ex13EnumTypeHandler {

    // 枚举顺序被重排（真实项目里很常见：有人在中间插了一个新枚举值）
    enum StatusV1 {
        NEW(10), ACTIVE(20), CLOSED(30);

        final int code;

        StatusV1(int code) {
            this.code = code;
        }
    }

    enum StatusV2 {
        ACTIVE(20), NEW(10), CLOSED(30);

        final int code;

        StatusV2(int code) {
            this.code = code;
        }
    }

    // EnumOrdinalTypeHandler：写 ordinal
    static int toOrdinal(StatusV1 s) {
        return s.ordinal();
    }

    // EnumTypeHandler（MyBatis 3.4.5+ 默认）：写 name
    static String toName(StatusV1 s) {
        return s.name();
    }

    // 自定义 TypeHandler：写业务 code
    static int toCode(StatusV1 s) {
        return s.code;
    }

    static StatusV2 readOrdinal(int ord) {
        return StatusV2.values()[ord];
    }

    static StatusV2 readName(String name) {
        return StatusV2.valueOf(name);
    }

    static StatusV2 readCode(int code) {
        for (StatusV2 s : StatusV2.values()) {
            if (s.code == code) {
                return s;
            }
        }
        throw new IllegalArgumentException("unknown code " + code);
    }

    public static void main(String[] args) {
        System.out.println("V1 order         : " + Arrays.toString(StatusV1.values()));
        System.out.println("V2 order         : " + Arrays.toString(StatusV2.values()));

        int ord = toOrdinal(StatusV1.ACTIVE);
        String name = toName(StatusV1.ACTIVE);
        int code = toCode(StatusV1.ACTIVE);
        System.out.println("write ordinal    : " + ord);
        System.out.println("write name       : " + name);
        System.out.println("write code       : " + code);

        StatusV2 byOrd = readOrdinal(ord);
        StatusV2 byName = readName(name);
        StatusV2 byCode = readCode(code);
        System.out.println("read by ordinal  : " + byOrd);
        System.out.println("read by name     : " + byName);
        System.out.println("read by code     : " + byCode);
        System.out.println("ordinal corrupted: " + (byOrd != StatusV2.ACTIVE));
        System.out.println("name corrupted   : " + (byName != StatusV2.ACTIVE));
        System.out.println("code corrupted   : " + (byCode != StatusV2.ACTIVE));
    }
}
